#!/usr/bin/env python3\nimport json, platform, shutil, subprocess\n\ndef get_gpus():\n    result = subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total,memory.free", "--format=csv,noheader"], capture_output=True, text=True, timeout=15)\n    lines = [l.strip() for l in result.stdout.splitlines() if l.strip()]\n    return [{"name": line.split(",")[0], "mem_total_gb": int(line.split(",")[1])//1024} for line in lines] if result.returncode==0 else []\n\ndef has_vllm():\n    try:\n        import vllm; return True\n    except Exception: return False\n\ndef has_lmdeploy():\n    try:\n        import lmdeploy; return True\n    except Exception: return False\n\ndef run_diagnose():\n    gpus = get_gpus()\n    data = {"host": platform.node(), "python_version": platform.python_version(), "gpu_count": len(gpus), "gpus": gpus, "has_vllm": has_vllm(), "has_lmdeploy": has_lmdeploy()}\n    print(json.dumps(data, indent=2))\n    return data
